// Decodificar base64 a binary y preparar para Gemini

const base64Data = $input.first().json.pdf_base64;
const filename = $input.first().json.filename;
const apiKey = $input.first().json.api_key;
const tipoRubrica = $input.first().json.tipo_rubrica;

if (!base64Data || !apiKey) {
  throw new Error("Faltan datos requeridos: pdf_base64 y api_key");
}

// Decodificar base64
const buffer = Buffer.from(base64Data, 'base64');

// Preparar para siguiente nodo
return [{
  json: {
    api_key: apiKey,
    tipo_rubrica: tipoRubrica,
    filename: filename
  },
  binary: {
    pdf: {
      data: buffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: filename || 'documento.pdf'
    }
  }
}];

// Construir body para Gemini con el PDF subido y el prompt de generación de rúbrica

const uploadResponse = $input.first().json;
const apiKey = $('Decodificar PDF').first().json.api_key;

// Verificar si hubo error en upload
if (uploadResponse.error) {
  throw new Error(`Error al subir PDF a Gemini: ${JSON.stringify(uploadResponse.error)}`);
}

const fileUri = uploadResponse.file?.uri;
if (!fileUri) {
  throw new Error("No se obtuvo URI del archivo subido");
}

// Prompt completo para generar rúbrica (del workflow original)
const prompt = `Rol del sistema
Sos un asistente experto en evaluación académica que convierte instrucciones de trabajos prácticos y exámenes (en PDF) en rúbricas JSON estandarizadas, completas y verificables.

Objetivo
A partir del contenido del PDF provisto, generá una rúbrica en JSON que describa con precisión cómo evaluar la entrega, incluyendo criterios, pesos, penalizaciones y metadatos. La salida debe ser un único objeto JSON válido (sin texto adicional).

Entrada

Un PDF de trabajo práctico, examen parcial o examen final (puede tener listas, consignas, tablas, consignas numeradas, etc.).

El PDF puede contener: objetivos, consignas, resultados de aprendizaje, formato de entrega, lenguaje/tecnología requerida, criterios de corrección, puntajes, notas y restricciones.

Salida (SOLO JSON, sin comentarios)

Un objeto que siga el esquema canónico de abajo.

Cumplí todas las reglas de "Normas de salida" y "Validaciones".

... (prompt completo sin cambios) ...

✔ mandatory_fail_conditions sólo si corresponde (sino []).`;

// Construir body para Gemini generateContent
const body = {
  generationConfig: {
    temperature: 0.3,
    topK: 40,
    topP: 0.95,
    responseMimeType: "text/plain"
  },
  contents: [
    {
      role: "user",
      parts: [
        {
          fileData: {
            fileUri: fileUri,
            mimeType: "application/pdf"
          }
        },
        {
          text: prompt
        }
      ]
    }
  ]
};

return [
  {
    json: {
      geminiBody: body,
      api_key: apiKey
    }
  }
];

// Extraer JSON de la respuesta (quitar ```json...```)

const geminiResponse = $input.first().json;

try {
  // Verificar errores de Gemini
  if (geminiResponse.error) {
    const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
    const errorCode = geminiResponse.error.code || 'UNKNOWN';

    return [{ 
      json: { 
        success: false,
        error: {
          code: "GEMINI_ERROR",
          message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
          retry: errorCode === 503 || errorCode === 500
        }
      } 
    }];
  }

  // Normalizar respuesta
  let responseArray;
  if (Array.isArray(geminiResponse)) {
    responseArray = geminiResponse;
  } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
    responseArray = geminiResponse.body;
  } else {
    responseArray = [geminiResponse];
  }

  const candidate = responseArray[0]?.candidates?.[0];
  if (!candidate) {
    return [{ 
      json: { 
        success: false,
        error: {
          code: "PARSING_ERROR",
          message: "No se encontró candidate en respuesta",
          retry: true
        }
      } 
    }];
  }

  const textContent = candidate.content?.parts?.[0]?.text;
  if (!textContent) {
    return [{ 
      json: { 
        success: false,
        error: {
          code: "PARSING_ERROR",
          message: "No se encontró texto en respuesta",
          retry: true
        }
      } 
    }];
  }

  // Extraer JSON (puede venir envuelto en ```json...```)
  let jsonText = textContent;
  const match = textContent.match(/```json\s*([\s\S]*?)```/i) || textContent.match(/```\s*([\s\S]*?)```/);
  if (match) {
    jsonText = match[1].trim();
  }

  // Parsear JSON
  const rubricaCompleta = JSON.parse(jsonText);

  // Pasar al siguiente nodo para mapeo
  return [{ json: { rubricaCompleta } }];

} catch (error) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "PARSING_ERROR",
        message: `Error al parsear JSON: ${error.message}`,
        retry: false
      }
    } 
  }];
}

// Mapear esquema complejo de Gemini al esquema simple del backend

const data = $input.first().json;

// Si hay error, pasarlo directamente
if (data.error) {
  return [{ json: data }];
}

const rubricaCompleta = data.rubricaCompleta;

if (!rubricaCompleta || !rubricaCompleta.criteria) {
  return [{ 
    json: { 
      success: false,
      error: {
        code: "PARSING_ERROR",
        message: "Rúbrica no contiene criterios",
        retry: false
      }
    } 
  }];
}

// Mapear criterios: weight (0-1) * 100 = puntaje_maximo
const criteriosSimples = rubricaCompleta.criteria.map(c => {
  return {
    nombre: c.name,
    descripcion: c.description,
    puntaje_maximo: Math.round(c.weight * 100)
  };
});

// Verificar que sumen aproximadamente 100
const sumaTotal = criteriosSimples.reduce((sum, c) => sum + c.puntaje_maximo, 0);
if (Math.abs(sumaTotal - 100) > 5) {
  // Ajustar el último criterio para que sume exactamente 100
  const diferencia = 100 - sumaTotal;
  criteriosSimples[criteriosSimples.length - 1].puntaje_maximo += diferencia;
}

// Construir descripción desde metadata
let descripcion = "";
if (rubricaCompleta.metadata?.source_pdf_title) {
  descripcion = rubricaCompleta.metadata.source_pdf_title;
} else if (rubricaCompleta.assessment_type) {
  descripcion = `Evaluación tipo ${rubricaCompleta.assessment_type}`;
}

// Construir respuesta en formato backend
const respuesta = {
  success: true,
  rubrica: {
    nombre_sugerido: rubricaCompleta.title || "Rúbrica Generada",
    descripcion: descripcion,
    puntaje_maximo: 100,
    criterios: criteriosSimples
  },
  metadata: {
    assessment_type: rubricaCompleta.assessment_type,
    language_or_stack: rubricaCompleta.language_or_stack || [],
    pages_parsed: rubricaCompleta.metadata?.pages_parsed || [],
    rubrica_completa: rubricaCompleta // Incluir la rúbrica completa por si es útil
  }
};

return [{ json: respuesta }];
